def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse left to right
            for j in range(0, len(grid[i])):
                if j % 2 == 0:
                    result.append(grid[i][j])
        else:
            # Traverse right to left
            for j in range(len(grid[i]) - 1, -1, -1):
                if j % 2 == 1:
                    result.append(grid[i][j])
    return result

from collections import Counter

def findValidPair(s: str) -> str:
    counts = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:  # Check if adjacent digits are different
            first_digit = int(s[i])
            second_digit = int(s[i + 1])
            if counts[s[i]] == first_digit and counts[s[i + 1]] == second_digit:
                return s[i] + s[i + 1]  # Return the valid pair
    return ""  # Return empty string if no valid pair is found

def maxDifference(s: str) -> int:
    from collections import Counter
    frequency = Counter(s)
    max_odd = float('-inf')
    min_even = float('inf')

    for count in frequency.values():
        if count % 2 == 0:
            min_even = min(min_even, count)
        else:
            max_odd = max(max_odd, count)

    return max_odd - min_even

