def totalNumbers(digits: List[int]) -> int:
    even_digits = [d for d in digits if d % 2 == 0]
    if not even_digits:
        return 0
    distinct_numbers = set()
    for last_digit in even_digits:
        for first_digit in set(digits):
            if first_digit == 0 and len(digits) > 1:
                continue  # skip leading zero for first digit
            # Counting occurrences of digits
            first_count = digits.count(first_digit)
            if first_count > 0:
                middle_candidates = digits.copy()
                middle_candidates.remove(first_digit)
                if digits.count(last_digit) > 1:
                    middle_candidates.append(last_digit)
                for middle_digit in set(middle_candidates):
                    # Ensure we only form 3-digit numbers with the last digit being even
                    if middle_digit != last_digit or middle_candidates.count(last_digit) > 1:
                        # Form the number
                        number = first_digit * 100 + middle_digit * 10 + last_digit
                        distinct_numbers.add(number)
    return len(distinct_numbers)

