def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = max(coins[0][0], 0)

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            for k in range(3):
                value = coins[i][j]
                if value >= 0:
                    if i > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k] + value)
                    if j > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k] + value)
                else:  # Robber encountered
                    if i > 0:
                        if k > 0:
                            dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k - 1])
                        dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k] - value)
                    if j > 0:
                        if k > 0:
                            dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k - 1])
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k] - value)

    result = max(dp[m - 1][n - 1])
    return max(result, 0)

