def maxFreeTime(eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
    n = len(startTime)
    gaps = []

    # Calculate initial gaps
    if startTime[0] > 0:
        gaps.append(startTime[0])  # Free time before the first meeting
    for i in range(1, n):
        gaps.append(startTime[i] - endTime[i - 1])  # Free time between meetings
    if endTime[-1] < eventTime:
        gaps.append(eventTime - endTime[-1])  # Free time after the last meeting

    # If no meetings can be rescheduled, return the maximum initial free time
    if k == 0:
        return max(gaps) if gaps else eventTime

    # If k is large enough to merge all meetings, calculate total duration
    total_duration = sum(endTime[i] - startTime[i] for i in range(n))
    if k >= n - 1:
        return eventTime - total_duration

    # Calculate the maximum free time possible after merging k gaps
    max_extra_gap = 0
    for i in range(len(gaps) - k):
        max_extra_gap += gaps[i]

    # Consider the largest k gaps for maximum free time
    if k > 0:
        largest_gaps = sorted(gaps[1:-1], reverse=True)[:k]  # Skip first last gap for merging
        max_extra_gap += sum(largest_gaps)

    return max(max_extra_gap, max(gaps))

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0
    for char in s:
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1
        # Calculate current distance
        current_distance = abs(x) + abs(y)
        max_distance = max(max_distance, current_distance)
    # Calculate maximum distance after k changes
    total_steps = len(s)
    additional_distance = min(k, total_steps)
    return max_distance + additional_distance
